const {chromium}=require('playwright');
const fs=require('fs');
(async()=>{
 const browser=await chromium.launch({headless:true,channel:'msedge'});
 const page=await browser.newPage({storageState:'.mtm-tmp/auth.json',viewport:{width:1440,height:1000}});
 const evidence='../answers/BUG-02/evidence/';
 const fixture=JSON.parse(fs.readFileSync(evidence+'bug-02-test-data.json'));
 await page.goto('http://localhost:3000/accounting');
 await page.getByRole('tab',{name:'Invoices',exact:true}).click();
 async function invoice(key,tc,file){
   const data=fixture.data.steps[tc];
   await page.getByRole('button',{name:'New invoice',exact:true}).click();
   await page.locator('#invCompany').click();
   await page.getByRole('option',{name:fixture.data.companies.find(c=>c.key===key).name,exact:true}).click();
   await page.getByLabel('Line 1 description',{exact:true}).fill(data.lineDescription);
   await page.getByLabel('Line 1 quantity',{exact:true}).fill(String(data.quantity));
   console.log(await page.getByRole('dialog').locator('input').evaluateAll(es=>es.map(e=>({label:e.getAttribute('aria-label'),id:e.id}))));
   await page.getByLabel('Line 1 unit price',{exact:true}).fill(data.unitPrice);
   await page.getByRole('button',{name:'Create draft',exact:true}).click();
   await page.getByRole('dialog').waitFor({state:'hidden'});
   const row=page.getByRole('row').filter({hasText:fixture.data.companies.find(c=>c.key===key).name}).first();
   await row.getByRole('button',{name:'Issue',exact:true}).click();
   await page.waitForTimeout(1000);
   console.log(tc,await row.innerText());
   await page.screenshot({path:evidence+file,fullPage:true});
 }
 await invoice('VND','BUG-02-TC-01','tc-01-vnd-invoice.png');
 await page.getByRole('tab',{name:'Payments',exact:true}).click();
 await page.getByRole('button',{name:'Record payment',exact:true}).click();
 await page.locator('#payCompany').click();
 await page.getByRole('option',{name:'Hoa Sen Trading MLD',exact:true}).click();
 await page.locator('#payInvoice').click();
 const opts=page.getByRole('option');
 await opts.last().click();
 await page.locator('#payAmount').fill(fixture.data.steps['BUG-02-TC-02'].amount);
 await page.getByRole('dialog').getByRole('button',{name:'Record payment',exact:true}).click();
 await page.getByRole('dialog').waitFor({state:'hidden'});
 await page.waitForTimeout(800);
 await page.getByRole('tab',{name:'Invoices',exact:true}).click();
 await page.waitForTimeout(500);
 console.log('payment',await page.getByRole('row').filter({hasText:'Hoa Sen Trading MLD'}).first().innerText());
 await page.screenshot({path:evidence+'tc-02-vnd-payment.png',fullPage:true});
 await invoice('USD','BUG-02-TC-03','tc-03-usd-invoice.png');
 await browser.close();
})();

