@import "tailwindcss";

/*
 * Solova design system — generated from design-token.json
 * ("Trello-Glass": Trello structure & palette on glassmorphism surfaces).
 * Semantic tokens are CSS custom properties that switch with `.dark`;
 * components consume them through Tailwind utilities mapped in @theme inline.
 */

@custom-variant dark (&:where(.dark, .dark *));

:root {
  /* canvas */
  --canvas-gradient: linear-gradient(135deg, #e4f0f6 0%, #8bbdd9 55%, #5ba4cf 100%);
  --canvas-solid: #bcd9ea;

  /* surfaces (glass) */
  --surface-glass: rgba(255, 255, 255, 0.7);
  --surface-glass-strong: rgba(255, 255, 255, 0.8);
  --surface-glass-subtle: rgba(255, 255, 255, 0.5);
  --surface-glass-overlay: rgba(255, 255, 255, 0.8);
  --surface-solid: #ffffff;
  --surface-raised: rgba(255, 255, 255, 0.9);
  --surface-hover: rgba(255, 255, 255, 0.9);
  --surface-selected: rgba(0, 121, 191, 0.15);

  /* borders */
  --border-glass: rgba(255, 255, 255, 0.35);
  --border-glass-subtle: rgba(255, 255, 255, 0.25);
  --border-default: #dfe1e6;
  --border-strong: #c1c7d0;
  --border-focus: #0079bf;

  /* text */
  --fg-primary: #172b4d;
  --fg-secondary: #5e6c84;
  --fg-subtle: #6b778c;
  --fg-onbrand: #ffffff;
  --fg-link: #026aa7;
  --fg-link-hover: #055a8c;
  --fg-disabled: #b3bac5;
  --fg-success: #61bd4f;
  --fg-warning: #ff9f1a;
  --fg-danger: #eb5a46;

  /* interactive */
  --int-primary: #0079bf;
  --int-primary-hover: #026aa7;
  --int-primary-active: #055a8c;
  --int-secondary: rgba(255, 255, 255, 0.6);
  --int-secondary-hover: rgba(255, 255, 255, 0.8);
  --int-subtle-hover: rgba(23, 43, 77, 0.08);
  --int-danger: #eb5a46;
  --int-danger-hover: #d04437;

  /* icons */
  --icon-primary: #42526e;
  --icon-subtle: #6b778c;
  --icon-brand: #0079bf;

  /* status surfaces */
  --status-success-bg: #e3fcef;
  --status-warning-bg: #fffae6;
  --status-danger-bg: #ffebe6;
  --status-info-bg: #deebff;
  --status-discovery-bg: #eae6ff;

  /* heatmap ramp */
  --heatmap-0: rgba(23, 43, 77, 0.08);
  --heatmap-1: #c6e48b;
  --heatmap-2: #7bc96f;
  --heatmap-3: #49a63a;
  --heatmap-4: #2e7d22;

  /* modal backdrop */
  --backdrop: rgba(23, 43, 77, 0.4);

  /* motion */
  --duration-fast: 120ms;
  --duration-base: 180ms;
  --duration-slow: 240ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-entrance: cubic-bezier(0, 0, 0.2, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
}

.dark {
  /* True black / neutral-dark glassmorphism (brand blue kept only for accents). */
  --canvas-gradient: linear-gradient(135deg, #0a0a0b 0%, #101012 55%, #17181c 100%);
  --canvas-solid: #0b0b0d;

  --surface-glass: rgba(20, 21, 24, 0.62);
  --surface-glass-strong: rgba(14, 15, 17, 0.74);
  --surface-glass-subtle: rgba(30, 31, 35, 0.5);
  --surface-glass-overlay: rgba(16, 17, 20, 0.82);
  --surface-solid: #141518;
  --surface-raised: rgba(28, 29, 33, 0.72);
  --surface-hover: rgba(255, 255, 255, 0.08);
  --surface-selected: rgba(41, 143, 202, 0.22);

