                <th scope="col" className="px-4 py-2.5 text-end font-medium">
                  Paid
                </th>
                <th scope="col" className="px-4 py-2.5 text-start font-medium">
                  Status
                </th>
                <th scope="col" className="px-4 py-2.5 text-end font-medium">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody>

