  createdAt         DateTime             @default(now()) @map("created_at") @db.Timestamptz(6)

  lines JournalLine[]

  @@index([entryDate])
  @@index([companyId])
  @@index([referenceType, referenceId])
  @@map("journal_entries")
}

model JournalLine {
